import java.util.Scanner;

public class lilu {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        char[] arr = str.toCharArray();

        int maxSize = 0;
        int currentSize = 0;
        int wordCount = 0;
        int state = 0; // 0 = outside parentheses, 1 = inside parentheses
        boolean wordStarted = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                state = 1;
                wordStarted = false;
            } else if (c == ')') {
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
                state = 0;
            } else if (state == 1) {
                if (!wordStarted && c != '_') {
                    wordCount++;
                    wordStarted = true;
                }
                if (c == '_') {
                    wordStarted = false;
                }
            } else {
                if (c != '_') {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

        System.out.println(maxSize + " " + wordCount);
    }
}
